function onLoad() {
   //Type appropriate comment here, and begin script below
   //a284e0261b7a30109fde86acdd4bcbfc - corrective action

   var hrService = g_form.getValue('hr_service');
   var userLanguage = g_lang;
   if(hrService == "a284e0261b7a30109fde86acdd4bcbfc" && userLanguage == "en"){
		g_form.setLabelOf('wi_who', 'Person responsible for the action');
		g_form.setLabelOf('wi_when', 'Action start date');
   }
}
